const items = $input.all();
const rows = items.map((item) => item.json || {});
const input = {};
for (const row of rows) {
  const key = String(row.Camp ?? row.camp ?? '').trim();
  if (!key || key.toLowerCase() === 'camp') continue;
  input[key] = row.Valor ?? row.valor ?? '';
}

const splitList = (value) => String(value || '').split(/[,;\r\n]+/).map((part) => part.trim()).filter(Boolean);
const quote = (value) => '"' + String(value).replace(/"/g, '').trim() + '"';
const unique = (arr) => [...new Set(arr.map((v) => String(v || '').trim()).filter(Boolean))];

const sector = String(input.sector || 'SaaS B2B').trim();
const zona = String(input.zona || 'Barcelona').trim();
const carrecs = splitList(input.carrecs_objectiu || 'CEO, Founder');
const paraules = splitList(input.paraules_clau || 'software');
const limit = Math.max(1, Math.min(25, Math.floor(Number(input.limit_resultats) || 5)));
const apifyMaxItems = Math.min(50, Math.max(limit, limit * 5));
const actorId = String(input.apify_actor_id || 'harvestapi~linkedin-profile-search').trim().replace('/', '~');
let sheetId = String(input.google_sheet_id || '1TQJGO7he2WAEyP67GpkD3ThT3bjeiVMhMdVlxGceRmA').trim();
const match = sheetId.match(/\/spreadsheets\/d\/([a-zA-Z0-9_-]+)/);
if (match) sheetId = match[1];

// Query m?s estricta: la zona va primer i els OR queden agrupats.
// Abans: CEO OR Founder ... "Barcelona" => massa ampli.
const roleQuery = carrecs.length ? '(' + carrecs.map(quote).join(' OR ') + ')' : '';
const keywordTerms = unique([sector, ...paraules].flatMap((v) => String(v || '').split(/[,;]+/)));
const keywordQuery = keywordTerms.length ? '(' + keywordTerms.map(quote).join(' OR ') + ')' : '';
const negativeQuery = '-student -intern -trainee -recruiter -jobs';
const query = [quote(zona), roleQuery, keywordQuery, negativeQuery].filter(Boolean).join(' ');

return [{ json: {
  sector,
  zona,
  carrecs_objectiu: carrecs,
  paraules_clau: paraules,
  limit_resultats: limit,
  apify_max_items: apifyMaxItems,
  apify_actor_id: actorId,
  google_sheet_id: sheetId,
  google_sheet_tab: String(input.google_sheet_tab || 'Leads').trim() || 'Leads',
  openai_model: String(input.openai_model || 'gpt-5-mini').trim(),
  search_query: query,
  data_captura: new Date().toISOString(),
}}];

const cfg = $input.first().json;
const tokenNames = ['APIFY_TOKEN_CLIENT_01', 'APIFY_TOKEN_CLIENT_02', 'APIFY_TOKEN_CLIENT_03', 'APIFY_TOKEN_CLIENT_04', 'APIFY_TOKEN_CLIENT_05', 'APIFY_TOKEN_CLIENT_06', 'APIFY_TOKEN_CLIENT_07', 'APIFY_TOKEN_CLIENT_08'];
const tokens = tokenNames.map((name) => ({ name, token: $env[name] })).filter((entry) => String(entry.token || '').trim());
if (!tokens.length) throw new Error('No hi ha cap APIFY_TOKEN_CLIENT_01...08 visible a n8n. Revisa EasyPanel i reinicia n8n.');

const actorInput = {
  profileScraperMode: 'Short',
  searchQuery: cfg.search_query,
  startPage: 1,
  takePages: 1,
  maxItems: cfg.apify_max_items || cfg.limit_resultats,
};

async function apifyRequest(options) {
  try {
    const body = await this.helpers.httpRequest({
      method: options.method || 'GET',
      url: options.url,
      qs: options.qs,
      headers: options.headers || {},
      body: options.body,
      json: true,
      timeout: 120000,
    });
    return { ok: true, body };
  } catch (error) {
    return {
      ok: false,
      status: error.statusCode || error.status || 0,
      body: error.response?.body || error.error || error.message || 'request failed',
    };
  }
}

const attempts = [];
for (const { name, token } of tokens) {
  const run = await apifyRequest.call(this, {
    method: 'POST',
    url: 'https://api.apify.com/v2/acts/' + cfg.apify_actor_id + '/runs',
    qs: { token, waitForFinish: 120 },
    headers: { Accept: 'application/json' },
    body: actorInput,
  });

  if (!run.ok) {
    attempts.push({ token_env_var: name, stage: 'run', status: run.status, error: run.body });
    continue;
  }

  const runData = run.body.data || run.body;
  if (runData.status !== 'SUCCEEDED') {
    attempts.push({ token_env_var: name, stage: 'run_status', status: runData.status, error: runData.statusMessage || '' });
    continue;
  }

  const datasetId = runData.defaultDatasetId;
  if (!datasetId) {
    attempts.push({ token_env_var: name, stage: 'dataset', status: 'NO_DATASET', error: 'No defaultDatasetId' });
    continue;
  }

  const dataset = await apifyRequest.call(this, {
    method: 'GET',
    url: 'https://api.apify.com/v2/datasets/' + datasetId + '/items',
    qs: { token, clean: 'true', limit: cfg.apify_max_items || cfg.limit_resultats },
    headers: { Accept: 'application/json' },
  });

  if (!dataset.ok) {
    attempts.push({ token_env_var: name, stage: 'items', status: dataset.status, error: dataset.body });
    continue;
  }

  return [{ json: { ...cfg, apify_token_env_var_used: name, apify_run_id: runData.id || '', raw_items: Array.isArray(dataset.body) ? dataset.body : [] } }];
}

throw new Error('Cap token Apify ha funcionat. Detall: ' + JSON.stringify(attempts).slice(0, 3000));

const cfg = $input.first().json;
const rawItems = Array.isArray(cfg.raw_items) ? cfg.raw_items : [];
const clean = (value) => {
  if (value === null || value === undefined) return '';
  if (typeof value === 'string' || typeof value === 'number') return String(value).trim();
  if (Array.isArray(value)) return clean(value[0]);
  return clean(value.linkedinText ?? value.text ?? value.name ?? value.title ?? value.value ?? '');
};
const norm = (value) => clean(value).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/\s+/g, ' ').trim();
const urlClean = (value) => clean(value).split('?')[0].replace(/\/$/, '').replace(/^http:/i, 'https:');
const hash = (text) => {
  let h = 2166136261;
  for (let i = 0; i < text.length; i++) h = Math.imul(h ^ text.charCodeAt(i), 16777619);
  return (h >>> 0).toString(36).toUpperCase();
};
const hasAny = (text, words) => {
  const hay = norm(text);
  return words.some((word) => word && hay.includes(norm(word)));
};
const geoWords = String(cfg.zona || '').split(/[,;\s]+/).map((w) => w.trim()).filter((w) => w.length >= 4);
const keywordWords = [...(cfg.paraules_clau || []), cfg.sector].flatMap((v) => String(v || '').split(/[,;\s]+/)).map((w) => w.trim()).filter((w) => w.length >= 3);
const roleRules = [
  ['CEO', /\b(ceo|chief executive officer|director general)\b/i],
  ['Founder', /\b(co-founder|founder|fundador|fundadora)\b/i],
  ['COO', /\b(coo|chief operating officer)\b/i],
  ['Director/a d\'Operacions', /\b(operations director|director of operations|operacions|operaciones)\b/i],
  ['Director', /\b(director|directora)\b/i],
];

const seen = new Set();
const out = [];
for (const raw of rawItems) {
  const first = clean(raw.firstName);
  const last = clean(raw.lastName);
  const name = clean(raw.fullName ?? raw.name) || [first, last].filter(Boolean).join(' ');
  const url = urlClean(raw.linkedinUrl ?? raw.profileUrl ?? raw.profileURL ?? raw.url);
  if (!name || !url) continue;

  const current = Array.isArray(raw.currentPosition) ? (raw.currentPosition[0] || {}) : (raw.currentPosition || {});
  const headline = clean(raw.headline ?? raw.position ?? raw.summary ?? raw.about).slice(0, 800);
  let title = clean(raw.position ?? raw.jobTitle ?? raw.title ?? current.position ?? current.title);
  if (!title && headline) {
    const found = roleRules.find(([, pattern]) => pattern.test(headline));
    if (found) title = found[0];
  }
  const company = clean(raw.companyName ?? raw.company ?? current.companyName ?? current.company?.name);
  const location = clean(raw.location ?? raw.geoLocation ?? raw.addressWithCountry ?? raw.city);

  const geoOk = !geoWords.length || hasAny(location, geoWords);
  if (!geoOk) continue;

  const key = norm(url);
  if (seen.has(key)) continue;
  seen.add(key);

  const relevanceText = [title, company, headline].join(' ');
  const relevanceOk = !keywordWords.length || hasAny(relevanceText, keywordWords) || hasAny(relevanceText, cfg.carrecs_objectiu || []);
  const notes = [];
  if (!location) notes.push('Ubicacio no detectada');
  if (!relevanceOk) notes.push('Revisar encaix: no coincideix clarament amb sector/keywords');
  if (!title) notes.push('Carrec no detectat');
  if (!company) notes.push('Empresa no detectada');

  out.push({ json: {
    'ID': 'LEAD-' + hash(key),
    'Data captura': cfg.data_captura,
    'Sector': cfg.sector,
    'Zona': cfg.zona,
    'Nom': name,
    'C?rrec': title,
    'Empresa': company,
    'URL LinkedIn': url,
    'Ubicaci?': location,
    'Headline': headline,
    'Estat lead': notes.length ? 'Revisar' : 'Nou',
    'Missatge LinkedIn suggerit': '',
    'Notes': notes.join(' | '),
    'Font': 'Apify ' + cfg.apify_actor_id + ' via ' + cfg.apify_token_env_var_used,
    'Duplicat?': 'No',
    '?ltima actualitzaci?': new Date().toISOString(),
  }});

  if (out.length >= cfg.limit_resultats) break;
}
return out;

const limitMessage = (value) => {
  const text = String(value || '').replace(/^[\s\"']+|[\s\"']+$/g, '').replace(/\s+/g, ' ').trim();
  if (Array.from(text).length <= 300) return text;
  return Array.from(text).slice(0, 297).join('').trim() + '...';
};

return $input.all().map((item) => {
  const j = item.json || {};
  let generated = '';
  if (Array.isArray(j.output)) {
    for (const block of j.output) {
      for (const content of (block.content || [])) {
        if (content.type === 'output_text' && content.text) generated += content.text;
      }
    }
  }
  generated = generated || j.output_text || '';
  const firstName = String(j['Nom'] || '').split(/\s+/)[0] || 'hola';
  const company = j['Empresa'] ? ' a ' + j['Empresa'] : '';
  const fallback = 'Hola ' + firstName + ', he vist el teu perfil' + company + '. A AImetos ajudem empreses a automatitzar processos repetitius amb agents IA per estalviar temps. T? sentit parlar-ne?';
  return { json: {
    'ID': j['ID'],
    'Data captura': j['Data captura'],
    'Sector': j['Sector'],
    'Zona': j['Zona'],
    'Nom': j['Nom'],
    'C?rrec': j['C?rrec'],
    'Empresa': j['Empresa'],
    'URL LinkedIn': j['URL LinkedIn'],
    'Ubicaci?': j['Ubicaci?'],
    'Headline': j['Headline'],
    'Estat lead': j['Estat lead'] || '',
    'Missatge LinkedIn suggerit': limitMessage(generated || fallback),
    'Notes': j['Notes'] || '',
    'Font': j['Font'],
    'Duplicat?': j['Duplicat?'],
    '?ltima actualitzaci?': new Date().toISOString(),
  }};
});
